package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="payments") public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @OneToOne @JoinColumn(name="order_id") Order order; String provider; String providerPaymentId; BigDecimal amount; String status; @Column(unique=true) String idempotencyKey; Instant createdAt=Instant.now(),updatedAt=Instant.now(); public Payment(){} public Payment(Order o,String p,BigDecimal a,String k){order=o;provider=p;amount=a;status="PENDING";idempotencyKey=k;} public String getStatus(){return status;} public void setStatus(String s){status=s;} public String getIdempotencyKey(){return idempotencyKey;} public BigDecimal getAmount(){return amount;} }
